insert into public.page_sections (page_id, section_key, section_type, label, sort_order, draft, published, published_at)
select id, 'faqs', 'Faqs', 'FAQs', 4, $json${"eyebrow":"FAQs","title":"Questions we get asked","lead":"Can't see yours? Call us and you will get a straight answer.","items":[{"q":"Do you supply operators?","a":"Operator-inclusive hire can be arranged. Where we supply an operator, they are competent and appropriately qualified for the machine and the application. Tell us in your quote request whether you need one."},{"q":"What capacity do I need?","a":"It depends on the load weight, the lift radius and height, and your site conditions. Send us those details and we will recommend a 40, 50 or 60-ton crane, a forklift or a telehandler. The final selection always follows the machine's load chart."},{"q":"Is there a minimum hire period?","a":"We hire by the day, the week and the month, and on long-term contracts. A one-day hire is fine for a single lift, an installation or an offload."},{"q":"Do you work weekends or emergencies?","a":"Our office hours are Monday to Friday, 07:00 to 17:00. For urgent or after-hours lifts, call 079 953 4581 and we will tell you what we can do."},{"q":"How is transport charged?","a":"Mobilisation is quoted together with the hire and depends on where your site is. Sites outside Mpumalanga, Gauteng and Limpopo can be arranged, subject to project requirements and transport costs."},{"q":"What do you need from me for a quote?","a":"The load weight and dimensions, the site location, your dates and how long you need the machine. Drawings or site photos help. If your site has its own safety or induction requirements, tell us up front so we can plan for them."},{"q":"Which areas do you cover?","a":"Mpumalanga is our primary service area, and we also work in Gauteng and Limpopo. Ask us about sites further afield."},{"q":"Can you help plan the lift?","a":"Yes. Every lift is planned around the equipment's approved capacity, the operating conditions, the manufacturer's specifications and the legal and site requirements that apply. Call us to talk through your lift."}]}$json$::jsonb, $json${"eyebrow":"FAQs","title":"Questions we get asked","lead":"Can't see yours? Call us and you will get a straight answer.","items":[{"q":"Do you supply operators?","a":"Operator-inclusive hire can be arranged. Where we supply an operator, they are competent and appropriately qualified for the machine and the application. Tell us in your quote request whether you need one."},{"q":"What capacity do I need?","a":"It depends on the load weight, the lift radius and height, and your site conditions. Send us those details and we will recommend a 40, 50 or 60-ton crane, a forklift or a telehandler. The final selection always follows the machine's load chart."},{"q":"Is there a minimum hire period?","a":"We hire by the day, the week and the month, and on long-term contracts. A one-day hire is fine for a single lift, an installation or an offload."},{"q":"Do you work weekends or emergencies?","a":"Our office hours are Monday to Friday, 07:00 to 17:00. For urgent or after-hours lifts, call 079 953 4581 and we will tell you what we can do."},{"q":"How is transport charged?","a":"Mobilisation is quoted together with the hire and depends on where your site is. Sites outside Mpumalanga, Gauteng and Limpopo can be arranged, subject to project requirements and transport costs."},{"q":"What do you need from me for a quote?","a":"The load weight and dimensions, the site location, your dates and how long you need the machine. Drawings or site photos help. If your site has its own safety or induction requirements, tell us up front so we can plan for them."},{"q":"Which areas do you cover?","a":"Mpumalanga is our primary service area, and we also work in Gauteng and Limpopo. Ask us about sites further afield."},{"q":"Can you help plan the lift?","a":"Yes. Every lift is planned around the equipment's approved capacity, the operating conditions, the manufacturer's specifications and the legal and site requirements that apply. Call us to talk through your lift."}]}$json$::jsonb, now()
